function pageHtml(slug,page){return `<main class="page-${slug}"><section class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="index.html">Home</a>　/　 ${page.title}</div><h1>${page.title}</h1><p>${page.desc}</p></div></section><section class="page-content pattern-surface"><div class="wrap"><figure><img src="${page.image}" alt="${page.caption}" loading="lazy"><figcaption>${page.caption}</figcaption></figure>${page.html}</div></section></main>`}
function initSlider(){const slides=[...document.querySelectorAll('.hero-slide')];if(!slides.length)return;const dots=document.querySelector('.hero-dots');let current=0,paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches,timer;dots.innerHTML='';slides.forEach((_,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',localizeText(`Show slide ${i+1}`,document.documentElement.lang));if(i===0)b.className='active';b.addEventListener('click',()=>{show(i);restart();});dots.append(b)});const dotBtns=[...dots.children];function show(i){current=(i+slides.length)%slides.length;slides.forEach((s,n)=>{s.classList.toggle('active',n===current);s.setAttribute('aria-hidden',n!==current)});dotBtns.forEach((d,n)=>{d.classList.toggle('active',n===current);d.setAttribute('aria-current',n===current?'true':'false')})}function restart(){clearInterval(timer);if(!paused)timer=setInterval(()=>show(current+1),6500)}function setPause(){const pause=document.querySelector('.hero-pause');if(!pause)return;const label=paused?'Play':'Pause';pause.dataset.paused=String(paused);pause.textContent=localizeText(label,document.documentElement.lang);pause.setAttribute('aria-label',localizeText(`${label} slide rotation`,document.documentElement.lang))}document.querySelector('.next')?.addEventListener('click',()=>{show(current+1);restart()});document.querySelector('.prev')?.addEventListener('click',()=>{show(current-1);restart()});const pause=document.querySelector('.hero-pause');if(pause){pause.addEventListener('click',()=>{paused=!paused;setPause();restart()});setPause();}const hero=document.querySelector('.hero');if(hero){hero.addEventListener('mouseenter',()=>clearInterval(timer));hero.addEventListener('mouseleave',restart);hero.addEventListener('focusin',()=>clearInterval(timer));hero.addEventListener('focusout',restart);hero.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(current-1);restart()}else if(e.key==='ArrowRight'){e.preventDefault();show(current+1);restart()}});}show(0);restart()}
function localizeText(value,lang){const dictionary=window.templeTranslations?.kn||{};return lang==='kn'?(dictionary[value]||value):value}
function applyLanguage(language,persist=true){const lang=language==='en'?'en':'kn';document.documentElement.lang=lang;document.querySelectorAll('[data-i18n-html-en]').forEach(node=>{node.innerHTML=lang==='kn'?node.getAttribute('data-i18n-html-kn'):node.getAttribute('data-i18n-html-en')});document.querySelectorAll('[data-i18n-en]').forEach(node=>{node.textContent=lang==='kn'?node.dataset.i18nKn:node.dataset.i18nEn});for(const attr of ['alt','aria-label','title','placeholder'])document.querySelectorAll(`[data-i18n-${attr}-en]`).forEach(node=>{node.setAttribute(attr,node.getAttribute(`data-i18n-${attr}-${lang}`))});document.querySelectorAll('[data-i18n-content-en]').forEach(node=>{node.content=node.getAttribute(`data-i18n-content-${lang}`)});const title=document.querySelector('title');if(title){const titleKn=window.templeTranslations?.kn?.[title.dataset.i18nEn]||title.dataset.i18nKn||title.textContent;document.title=lang==='kn'?titleKn:title.dataset.i18nEn||title.textContent}document.querySelectorAll('.language-switch [data-lang]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===lang)));document.querySelectorAll('.hero-dots button').forEach((button,index)=>button.setAttribute('aria-label',localizeText(`Show slide ${index+1}`,lang)));const pauseButton=document.querySelector('.hero-pause');if(pauseButton){const label=pauseButton.dataset.paused==='true'?'Play':'Pause';pauseButton.textContent=localizeText(label,lang);pauseButton.setAttribute('aria-label',localizeText(`${label} slide rotation`,lang))}if(persist){try{localStorage.setItem('temple-language',lang);sessionStorage.setItem('temple-language',lang)}catch{}}}
